import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Date-Construction.md","filePath":"manual-en/Date-Construction.md","lastUpdated":1785684581000}'),o={name:"manual-en/Date-Construction.md"};function s(d,e,i,p,h,f){return a(),n("div",null,[...e[0]||(e[0]=[r('<h4 id="_7-7-8-4-functions-that-produce-dates" tabindex="-1">7.7.8.4 Functions that Produce Dates <a class="header-anchor" href="#_7-7-8-4-functions-that-produce-dates" aria-label="Permalink to &quot;7.7.8.4 Functions that Produce Dates&quot;">​</a></h4><p>These functions take numeric arguments and give numeric results that represent dates. Arguments taken by these functions are:</p><p>day</p><p>Refers to a day of the month between 1 and 31. Day 0 is also accepted and refers to the final day of the previous month. Days 29, 30, and 31 are accepted even in months that have fewer days and refer to a day near the beginning of the following month.</p><p>month</p><p>Refers to a month of the year between 1 and 12. Months 0 and 13 are also accepted and refer to the last month of the preceding year and the first month of the following year, respectively.</p><p>quarter</p><p>Refers to a quarter of the year between 1 and 4. The quarters of the year begin on the first day of months 1, 4, 7, and 10.</p><p>week</p><p>Refers to a week of the year between 1 and 53.</p><p>yday</p><p>Refers to a day of the year between 1 and 366.</p><p>year</p><p>Refers to a year, 1582 or greater. Years between 0 and 99 are treated according to the epoch set on SET EPOCH, by default beginning 69 years before the current date (see <a href="./SET#SET-EPOCH">SET EPOCH</a>).</p><p>If these functions’ arguments are out-of-range, they are correctly normalized before conversion to date format. Non-integers are rounded toward zero.</p><p>Function: __<strong>DATE.DMY</strong> <em>( day, month, year)</em> Function: __<strong>DATE.MDY</strong> <em>( month, day, year)</em></p><p>Results in a date value corresponding to the midnight before day day of month month of year year.</p><p>Function: __<strong>DATE.MOYR</strong> <em>( month, year)</em></p><p>Results in a date value corresponding to the midnight before the first day of month month of year year.</p><p>Function: __<strong>DATE.QYR</strong> <em>( quarter, year)</em></p><p>Results in a date value corresponding to the midnight before the first day of quarter quarter of year year.</p><p>Function: __<strong>DATE.WKYR</strong> <em>( week, year)</em></p><p>Results in a date value corresponding to the midnight before the first day of week week of year year.</p><p>Function: __<strong>DATE.YRDAY</strong> <em>( year, yday)</em></p><p>Results in a date value corresponding to the day yday of year year.</p>',25)])])}const y=t(o,[["render",s]]);export{u as __pageData,y as default};
